use crate::wasi::clocks::wall_clock;

struct Node;

/// Civil date (year, month, day) from days since the Unix epoch.
/// Howard Hinnant's algorithm; valid across the full u64 seconds range we see.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The one node that holds the clock reads it here.
        let now = wall_clock::now();
        let secs = now.seconds;

        let days = (secs / 86_400) as i64;
        let (year, month, day) = civil_from_days(days);

        // Exactly 10 characters for any year in [0, 9999]: "YYYY-MM-DD".
        let date = format!("{:04}-{:02}-{:02}", year, month, day);

        RunInfo {
            date,          // ensures len(date) == 10
            started: secs, // ensures started >= 0 (u64 is non-negative by type)
        }
    }
}

export!(Node);
```

